#ifndef MEP_ZIG_LSP_H
#define MEP_ZIG_LSP_H

// The analysis half of mep's own Zig language server (the wire half is
// zig_lsp_server.cpp, the `mep-zig-lsp` binary; the `zig_ls` entry
// in main.cpp's kBuiltinLsp spawns it). Everything here is a pure function
// of the document text, so the whole server is testable without a client
// (zig_lsp_test.cpp). Positions are 0-based lines and 0-based byte
// columns (`positionEncoding: "utf-8"`).
//
// Generated by tools/new_language.py; nix_lsp.h is the worked example of
// every function below.

#include <memory>
#include <string>
#include <vector>

struct ZigLspRange {
    int line = 0, col = 0, end_line = 0, end_col = 0;
};

class ZigLspDocument;

/** @brief Parses and analyses a document; every query below runs on the result. */
std::shared_ptr<const ZigLspDocument> ZigLspAnalyze(const std::vector<std::string> &lines);

// --- Diagnostics ------------------------------------------------------------------

enum class ZigLspSeverity { Error = 1, Warning = 2, Information = 3, Hint = 4 };

struct ZigLspDiagnostic {
    ZigLspRange range;
    ZigLspSeverity severity = ZigLspSeverity::Error;
    std::string code;  // stable id: syntax-error, ...
    std::string message;
    bool unnecessary = false;  // LSP DiagnosticTag.Unnecessary
    bool deprecated = false;   // LSP DiagnosticTag.Deprecated
};

std::vector<ZigLspDiagnostic> ZigLspDiagnostics(const ZigLspDocument &doc);
/** @brief `path:line:col: severity: message [code]`, 1-based, as `--lint` prints it. */
std::string ZigLspFormatDiagnostic(const std::string &path, const ZigLspDiagnostic &d);
/** @brief Whether a diagnostic makes `--lint` exit non-zero (an error or a warning). */
bool ZigLspDiagnosticFails(const ZigLspDiagnostic &d);

// --- Completion / hover / signature help -------------------------------------------

enum class ZigLspKind {
    Text = 1, Method = 2, Function = 3, Field = 5, Variable = 6, Class = 7, Module = 9, Property = 10,
    Value = 12, Keyword = 14, Snippet = 15, Constant = 21, Struct = 22,
};

struct ZigLspCompletionItem {
    std::string label;
    std::string insert_text;
    ZigLspKind kind = ZigLspKind::Text;
    std::string detail;
    std::string documentation;
    int replace_start = 0, replace_end = 0;  // byte columns on the request's line
};

std::vector<ZigLspCompletionItem> ZigLspCompletions(const ZigLspDocument &doc, int line, int col);

struct ZigLspHoverInfo {
    bool found = false;
    std::string text;  // markdown
    ZigLspRange range;
};

ZigLspHoverInfo ZigLspHover(const ZigLspDocument &doc, int line, int col);

struct ZigLspSignatureHelp {
    bool found = false;
    std::string label;
    std::vector<std::string> params;  // substrings of label
    std::string documentation;
    int active_param = 0;
};

ZigLspSignatureHelp ZigLspSignatureAt(const ZigLspDocument &doc, int line, int col);

// --- Navigation -------------------------------------------------------------------------

struct ZigLspLocation {
    ZigLspRange range;
};

std::vector<ZigLspLocation> ZigLspDefinition(const ZigLspDocument &doc, int line, int col);

struct ZigLspReference {
    ZigLspRange range;
    bool is_definition = false;
};

std::vector<ZigLspReference> ZigLspReferences(const ZigLspDocument &doc, int line, int col);

struct ZigLspTextEdit {
    ZigLspRange range;
    std::string new_text;
};

struct ZigLspRenameTarget {
    bool found = false;
    ZigLspRange range;
    std::string placeholder;
};

ZigLspRenameTarget ZigLspPrepareRename(const ZigLspDocument &doc, int line, int col);
std::vector<ZigLspTextEdit> ZigLspRename(const ZigLspDocument &doc, int line, int col,
                                               const std::string &new_name, std::string *error);

// --- Outline / folding --------------------------------------------------------------------

enum class ZigLspSymbolKind {
    File = 1, Module = 2, Namespace = 3, Class = 5, Method = 6, Property = 7, Field = 8, Function = 12,
    Variable = 13, Constant = 14, String = 15, Number = 16, Boolean = 17, Array = 18, Object = 19, Key = 20,
    Null = 21,
};

struct ZigLspSymbol {
    std::string name;
    std::string detail;
    ZigLspSymbolKind kind = ZigLspSymbolKind::Variable;
    ZigLspRange range;
    ZigLspRange sel_range;
    int parent = -1;
};

std::vector<ZigLspSymbol> ZigLspSymbols(const ZigLspDocument &doc);

struct ZigLspFold {
    int start_line = 0, end_line = 0;
    std::string kind;  // "" or "comment"
};

std::vector<ZigLspFold> ZigLspFolds(const ZigLspDocument &doc);

// --- Formatting ------------------------------------------------------------------------------

/** @brief The formatter as one edit over the changed lines; none when already formatted. */
std::vector<ZigLspTextEdit> ZigLspFormat(const std::vector<std::string> &lines, int width, std::string *error);

#endif  // MEP_ZIG_LSP_H
